import type { Metadata } from 'next';
import { SITE } from './public-content';

/** Static 1200×630 social card, generated by `npm run og:generate`. */
export const DEFAULT_OG_IMAGE = '/og/og-default.png';

/**
 * Joins a route path onto the configured site origin while preserving any
 * base path (the GitHub Pages deployment serves from `/Portfolio`).
 */
export function absoluteUrl(path: string): string {
  const base = SITE.url.replace(/\/+$/, '');
  if (!path || path === '/') return `${base}/`;
  return `${base}${path.startsWith('/') ? path : `/${path}`}`;
}

/**
 * Prefixes site-local paths but leaves already-absolute URLs alone. Admin
 * free-text fields (e.g. a post's `coverImage`) may legitimately point at a
 * CDN, and prefixing those would produce a nested, broken URL.
 */
function toAbsoluteImage(src: string): string {
  return /^(?:[a-z][a-z0-9+.-]*:)?\/\//i.test(src) ? src : absoluteUrl(src);
}

/**
 * Canonical + Open Graph + Twitter metadata for a public page. Canonical URLs
 * are absolute so they stay correct under a base path.
 */
export function pageMetadata({
  title,
  description,
  path,
  type = 'website',
  absoluteTitle = false,
  socialTitle,
  images,
  article,
}: {
  title: string;
  description: string;
  path: string;
  type?: 'website' | 'article';
  /** Skip the `%s — Site` title template (used by the home page). */
  absoluteTitle?: boolean;
  /** Override the generated social title. */
  socialTitle?: string;
  images?: string[];
  article?: { publishedTime?: string; authors?: string[] };
}): Metadata {
  const url = absoluteUrl(path);
  const social = socialTitle ?? `${title} — ${SITE.shortName}`;
  const ogImages = (images?.length ? images : [DEFAULT_OG_IMAGE])
    .filter(Boolean)
    .map((src) => ({ url: toAbsoluteImage(src) }));

  const openGraph: Metadata['openGraph'] =
    type === 'article'
      ? {
          title: social,
          description,
          url,
          siteName: SITE.shortName,
          locale: SITE.locale,
          type: 'article',
          images: ogImages,
          ...(article?.publishedTime ? { publishedTime: article.publishedTime } : {}),
          ...(article?.authors?.length ? { authors: article.authors } : {}),
        }
      : {
          title: social,
          description,
          url,
          siteName: SITE.shortName,
          locale: SITE.locale,
          type: 'website',
          images: ogImages,
        };

  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: url },
    openGraph,
    twitter: {
      card: 'summary_large_image',
      title: social,
      description,
      images: ogImages.map((image) => image.url),
    },
  };
}
